 static HttpRequest.Builder request(String uri,String cookie){var r=HttpRequest.newBuilder(URI.create(uri)).timeout(Duration.ofSeconds(10));if(cookie!=null)r.header("Cookie",cookie);return r;}
 static HttpResponse<String> send(HttpClient http,HttpRequest.Builder r)throws Exception{return http.send(r.build(),HttpResponse.BodyHandlers.ofString());}
